package io.forgeloop.support.config;
import io.forgeloop.support.domain.Member; import io.forgeloop.support.domain.MemberRepository; import io.forgeloop.support.domain.Organization; import io.forgeloop.support.domain.OrganizationRepository; import io.forgeloop.support.domain.Role; import io.forgeloop.support.domain.Ticket; import io.forgeloop.support.domain.TicketRepository; import org.springframework.boot.CommandLineRunner; import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty; import org.springframework.context.annotation.Bean; import org.springframework.context.annotation.Configuration;
@Configuration @ConditionalOnProperty(name="forgeloop.demo-data.enabled",havingValue="true") public class DemoData { @Bean CommandLineRunner seed(OrganizationRepository orgs,MemberRepository members,TicketRepository tickets){return args->{if(orgs.count()>0)return; Organization acme=orgs.save(new Organization("org-acme","Acme Corp")); Organization other=orgs.save(new Organization("org-other","Other Co")); members.save(new Member("admin-1","Avery Admin",Role.ADMIN,acme)); members.save(new Member("member-1","Morgan Member",Role.MEMBER,acme)); members.save(new Member("outsider-1","Ollie Outsider",Role.MEMBER,other)); tickets.save(new Ticket("ticket-142","Cannot export monthly report",acme));};} }
